package com.security.demo.util; import io.jsonwebtoken.*; import org.springframework.stereotype.Component; import java.util.*; @Component public class JwtUtil { private final String SECRET="${JWT_SECRET:mysecretkey}"; public String generateToken(String u){ return Jwts.builder().setSubject(u).setIssuedAt(new Date()).setExpiration(new Date(System.currentTimeMillis()+1800000)).signWith(SignatureAlgorithm.HS256,SECRET).compact(); } public String extractUsername(String t){ return Jwts.parser().setSigningKey(SECRET).parseClaimsJws(t).getBody().getSubject(); }}